package in.chinatech.phoneassistant;
import java.io.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.spec.*;import java.util.*;
/** JVM cryptographic/wire negatives use a separate throwaway signing key, never a production signer. */
public final class PhoneGateCoreTest {
 static int assertions;interface Work{void run()throws Exception;}static void ok(boolean yes,String label){assertions++;if(!yes)throw new AssertionError(label);}static void reject(Work work,String label)throws Exception {boolean failed=false;try{work.run();}catch(IOException|GeneralSecurityException e){failed=true;}ok(failed,label);}
 static final Map<String,Map<String,Object>> documents=new HashMap<>();static int serial;
 static final PhoneGateCore.Json json=new PhoneGateCore.Json(){public Map<String,Object> read(String key)throws Exception{Map<String,Object> map=documents.get(key);if(map==null)throw new IOException("JSON");return map;}public String write(Map<String,Object> map){String key="fixture-"+(++serial);documents.put(key,new HashMap<>(map));return key;}};
 static String envelope(Map<String,Object> claims,KeyPair key)throws Exception {String p=PhoneGateCore.b64(json.write(claims).getBytes(StandardCharsets.UTF_8));Signature s=Signature.getInstance("SHA256withECDSA");s.initSign(key.getPrivate());s.update(("CT-OFFICE-V3-UPDATE\n"+p).getBytes(StandardCharsets.UTF_8));return "fixture."+p+"."+PhoneGateCore.b64(PhoneGateCore.derToRaw(s.sign()));}
 public static void main(String[] args)throws Exception {
  KeyPairGenerator g=KeyPairGenerator.getInstance("EC");g.initialize(new ECGenParameterSpec("secp256r1"));KeyPair key=g.generateKeyPair();Map<String,String> trust=Collections.singletonMap("fixture",Base64.getEncoder().encodeToString(key.getPublic().getEncoded()));
  for(int i=0;i<256;i++){Signature s=Signature.getInstance("SHA256withECDSA");s.initSign(key.getPrivate());s.update(new byte[]{(byte)i});byte[] der=s.sign(),raw=PhoneGateCore.derToRaw(der);ok(raw.length==64,"fixed P1363");s.initVerify(key.getPublic());s.update(new byte[]{(byte)i});ok(s.verify(PhoneGateCore.rawToDer(raw)),"DER and P1363 interoperate");}
  reject(()->PhoneGateCore.derToRaw(new byte[]{48,0}),"short DER");reject(()->PhoneGateCore.rawToDer(new byte[65]),"wrong P1363");reject(()->PhoneGateCore.un64("YQ==",10),"no padded aliases");reject(()->PhoneGateCore.un64("YR",10),"no noncanonical base64");reject(()->PhoneGateCore.utf8(new byte[]{(byte)0xff}),"strict UTF8");
  long now=1800000000L;String a=UUID.randomUUID().toString(),b=UUID.randomUUID().toString(),ja=UUID.randomUUID().toString(),jb=UUID.randomUUID().toString(),h="a".repeat(64),other="b".repeat(64);
  PhoneGateCore.Plan plan=new PhoneGateCore.Plan(String.join("|","CTPA5P",ProtocolCore.token(16),a,b,ja,jb,h,other,ProtocolCore.token(16),h,h,"100001","9223372036854775807"));ok(plan.count==100001,"no historical 10000 cap");ok(plan.bytes==Long.MAX_VALUE,"64-bit totals");ok(plan.encode().equals(new PhoneGateCore.Plan(plan.encode()).encode()),"canonical plan");ok(!plan.scope().equals(new PhoneGateCore.Plan(plan.encode().replace("100001","100002")).scope()),"count frozen into scope");reject(()->new PhoneGateCore.Plan(plan.encode().replace("100001","0")),"empty task blocked");reject(()->new PhoneGateCore.Plan(plan.encode().replace(Long.toString(Long.MAX_VALUE),"9223372036854775808")),"overflow blocked");reject(()->new PhoneGateCore.Plan(plan.encode().replace(b,a)),"same instance blocked");reject(()->PhoneGateCore.code("CTSS4|legacy","CTPA5O",8),"old peer no downgrade");reject(()->PhoneGateCore.code("CTPA5O|"+"x".repeat(2200),"CTPA5O",8),"bounded QR");
  Map<String,Object> claims=new LinkedHashMap<>();claims.put("v",1);claims.put("iss",PhoneGateCore.ORIGIN);claims.put("aud","toolbox-v1-task");claims.put("toolId",PhoneGateCore.TOOL);claims.put("releaseId",PhoneGateCore.RELEASE);claims.put("installationId",a);claims.put("jobId",ja);claims.put("action","receive");claims.put("scopeHash",plan.scope());claims.put("keyHash",h);claims.put("issuedAt",now);claims.put("expiresAt",now+2592000);
  String signed=envelope(claims,key);ok(PhoneGateCore.permit(signed,PhoneGateCore.RELEASE,a,ja,"receive",plan.scope(),h,json,trust,now)!=null,"original permit accepted");
  for(String field:new String[]{"iss","aud","toolId","releaseId","installationId","jobId","action","scopeHash","keyHash"}){Map<String,Object> changed=new HashMap<>(claims);changed.put(field,"wrong");String corrupt=envelope(changed,key);reject(()->PhoneGateCore.permit(corrupt,PhoneGateCore.RELEASE,a,ja,"receive",plan.scope(),h,json,trust,now),"reject binding "+field);}
  for(String field:new String[]{"issuedAt","expiresAt","v"}){Map<String,Object> changed=new HashMap<>(claims);changed.put(field,field.equals("v")?2L:field.equals("issuedAt")?now+301:now);String corrupt=envelope(changed,key);reject(()->PhoneGateCore.permit(corrupt,PhoneGateCore.RELEASE,a,ja,"receive",plan.scope(),h,json,trust,now),"reject time/version "+field);}
  reject(()->PhoneGateCore.verify(signed.substring(0,signed.length()-3)+"abc","toolbox-v1-task",json,trust,now),"forged signature");reject(()->PhoneGateCore.verify(signed,"toolbox-v1-task",json,Collections.emptyMap(),now),"unknown key");reject(()->PhoneGateCore.verify(signed,"toolbox-v1-task",json,trust,now+2592000),"expired original permit");
  Map<String,Object> body=new HashMap<>();body.put("requestId",ja);body.put("installationId",a);body.put("timestamp",now);body.put("nonce",PhoneGateCore.b64(new byte[32]));String p=PhoneGateCore.b64("{}".getBytes(StandardCharsets.UTF_8));String canonical=PhoneGateCore.canonical("/api/toolbox/client/v1/phone-assistant/jobs/start",p,body);ok(canonical.startsWith("CT-TOOLBOX-V1\nPOST\n/api/toolbox/client/v1/phone-assistant/jobs/start\n"),"actual route proof");ok(canonical.endsWith("\n"+PhoneGateCore.hash("")),"empty bearer proof");
  System.out.println("{\"suite\":\"phone-gate-core\",\"assertions\":"+assertions+",\"physicalDeviceProof\":false}");
 }
}
